#include "../../05-数学/模意义与异或高斯消元.cpp"
int main(){mt19937 g(127);for(int p:{2,3,5,7})for(int z=0;z<400;z++){int m=g()%5,n=g()%7;vector<vector<ll>>a(n,vector<ll>(m+1));for(auto &row:a)for(auto &v:row)v=int(g()%15)-7;int total=1;for(int j=0;j<m;j++)total*=p;int count=0;auto valid=[&](const vector<ll>&x){for(auto row:a){ll s=-row[m];for(int j=0;j<m;j++)s+=row[j]*x[j];if(s%p)return false;}return true;};for(int mask=0;mask<total;mask++){int v=mask;vector<ll>x(m);for(auto &u:x)u=v%p,v/=p;if(valid(x))count++;}vector<ll>x;int status=gauss_mod(a,m,p,x);assert(status==(count==0?-1:count==1?0:1));if(count)assert(valid(x));if(p==2){vector<bitset<16>>b(n);for(int i=0;i<n;i++)for(int j=0;j<=m;j++)b[i][j]=(a[i][j]%2)!=0;bitset<16>y;int rank;assert(gauss_xor(b,m,y,rank)==status);if(count){vector<ll>v(m);for(int j=0;j<m;j++)v[j]=y[j];assert(valid(v)&&count==(1<<(m-rank)));}}}vector<vector<ll>>a={{1,1,3},{1,-1,1}};vector<ll>x;assert(gauss_mod(a,2,2305843009213693951LL,x)==0&&x[0]==2&&x[1]==1);cout<<"Gauss OK\n";}
